import numpy as np, pandas as pd
from scipy.optimize import least_squares
d=df.copy()
S=d.S.values; I=d.I.values; v=d.v.values
def mk(kind):
    def f(p,S,I):
        Vm=np.exp(p[0]); Km=np.exp(p[1]); Ki=np.exp(p[2]); Kip=np.exp(p[3]) if len(p)>3 else 1e9
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='uncomp': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='noncomp': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='mixed': return Vm*S/(Km*(1+I/Ki)+S*(1+I/Kip))
    return f
